mapper.select:
WITH moved AS (
  INSERT INTO work_sighting (work_id, layer, source_id, first_seen)
  SELECT #{toWork}, layer, source_id, first_seen FROM work_sighting WHERE work_id = #{fromWork}
  ON CONFLICT DO NOTHING
  RETURNING 1
), dropped AS (
  DELETE FROM work_sighting WHERE work_id = #{fromWork}
)
SELECT count(*)::int FROM moved
